package net.mcreator.eldervale.stats;

import net.neoforged.neoforge.registries.NeoForgeRegistries;
import net.neoforged.neoforge.registries.DeferredRegister;
import net.neoforged.neoforge.attachment.AttachmentType;

import net.mcreator.eldervale.EldervaleMod;

import java.util.function.Supplier;

/**
 * Separate from EldervaleModVariables on purpose: that file is generated by MCreator.
 * Registered in the "mod constructor" user code block of EldervaleMod.
 */
public final class StatsAttachments {
	private StatsAttachments() {
	}

	public static final DeferredRegister<AttachmentType<?>> ATTACHMENT_TYPES = DeferredRegister.create(NeoForgeRegistries.Keys.ATTACHMENT_TYPES, EldervaleMod.MODID);

	/** copyOnDeath: the invested points survive death. Logout and restart are covered by the serialization. */
	public static final Supplier<AttachmentType<PlayerAttributes>> PLAYER_ATTRIBUTES = ATTACHMENT_TYPES.register("player_attributes", () -> AttachmentType.serializable(() -> new PlayerAttributes()).copyOnDeath().build());
}
